import {validate,simulate} from './engine.mjs';
export const DEFAULT={reserve:100,rate:1,floor:10,provider:24,fallback:true,crash:true,fees:false};
const KEY='battery.workspace.v1',MAX_BYTES=250000;
const plain=x=>x!==null&&typeof x==='object'&&!Array.isArray(x);
function title(x){if(typeof x!=='string'||!x.trim()||x.length>80||/[\x00-\x1f\x7f]/.test(x))throw Error('Use a name with 1 to 80 printable characters.');return x.trim();}
function identity(x){if(typeof x!=='string'||!/^[-a-zA-Z0-9_]{1,80}$/.test(x))throw Error('Invalid record ID.');return x;}
function stamp(x){if(typeof x!=='string'||!Number.isFinite(Date.parse(x)))throw Error('Invalid saved timestamp.');return x;}
function record(x,run=false){if(!plain(x))throw Error('Invalid record.');return {id:identity(x.id),name:title(x.name),createdAt:stamp(x.createdAt),updatedAt:stamp(x.updatedAt),scenario:validate(x.scenario),...(run?{kind:'simulation',engine:'battery.simulation/1'}:{})};}
function workspace(x){if(!plain(x)||x.schema!=='battery.workspace/1'||!Array.isArray(x.policies)||!Array.isArray(x.runs)||x.policies.length>100||x.runs.length>200)throw Error('Invalid workspace: maximum 100 policies and 200 tests.');const result={schema:x.schema,policies:x.policies.map(p=>record(p)),runs:x.runs.map(r=>{if(r.kind!=='simulation'||r.engine!=='battery.simulation/1')throw Error('Unsupported test engine.');return record(r,true);})};for(const list of [result.policies,result.runs])if(new Set(list.map(x=>x.id)).size!==list.length)throw Error('Duplicate record IDs.');return result;}
const empty=()=>({schema:'battery.workspace/1',policies:[],runs:[]});
export function parseWorkspace(text){if(typeof text!=='string'||new TextEncoder().encode(text).length>MAX_BYTES)throw Error('Import must be below 250 KB.');return workspace(JSON.parse(text));}
export function createStore(storage){function read(){let raw;try{raw=storage.getItem(KEY);}catch{throw Error('Browser storage is unavailable. Enable storage to save policies and tests.');}return raw===null?empty():parseWorkspace(raw);}function write(data){const clean=workspace(data);try{storage.setItem(KEY,JSON.stringify(clean));}catch{throw Error('Could not save. Export your workspace or free browser storage.');}return clean;}
 return {read,export:()=>JSON.stringify(read(),null,2),savePolicy(name,scenario,id){const data=read(),now=new Date().toISOString(),existing=id?data.policies.find(p=>p.id===id):null;if(id&&!existing)throw Error('Policy no longer exists. Save it as a new policy.');const p=record({id:existing?.id??crypto.randomUUID(),name,scenario,createdAt:existing?.createdAt??now,updatedAt:now});data.policies=existing?data.policies.map(x=>x.id===id?p:x):[p,...data.policies];write(data);return p;},saveRun(name,scenario){const data=read(),now=new Date().toISOString(),r=record({id:crypto.randomUUID(),name,scenario,createdAt:now,updatedAt:now},true);data.runs.unshift(r);write(data);return r;},removePolicy(id){const data=read();data.policies=data.policies.filter(x=>x.id!==id);write(data);},import(text){const incoming=parseWorkspace(text),data=read();for(const key of ['policies','runs']){const seen=new Set(data[key].map(x=>x.id));for(const item of incoming[key]){if(!seen.has(item.id)){data[key].push(item);seen.add(item.id);}}}write(data);return {policies:incoming.policies.length,runs:incoming.runs.length};}};
}
let store;export function browserStore(){return store??=createStore({getItem:key=>localStorage.getItem(key),setItem:(key,value)=>localStorage.setItem(key,value)});}
export function resultOf(run){return simulate(run.scenario);}
